import pypdf, docx, openpyxl, glob

def read_pdf(p):
    print('=== PDF:', p)
    r = pypdf.PdfReader(p)
    for i, page in enumerate(r.pages):
        print(f'--- Page {i+1} ---')
        print(page.extract_text())

def read_docx(p):
    print('=== DOCX:', p)
    d = docx.Document(p)
    for para in d.paragraphs:
        if para.text.strip(): print(para.text)
    for t in d.tables:
        for row in t.rows:
            print([c.text.strip() for c in row.cells])

