import fitz, openpyxl, glob

def dump_pdf(p):
    print('=== PDF:', p)
    doc = fitz.open(p)
    for page in doc:
        print(page.get_text())

def dump_xlsx(p):
    print('=== XLSX:', p)
    wb = openpyxl.load_workbook(p, data_only=True)
    for s in wb.sheetnames:
        print('--- Sheet:', s)
        for row in wb[s].iter_rows(values_only=True):
            if any(row):
                print(row)

for p in sorted(glob.glob('/filesystem/**/*Halbray*', recursive=True) + glob.glob('/filesystem/**/*Kelloway*', recursive=True) + ['/filesystem/Equipment/SOC_PTO_Hold_Log.xlsx', '/filesystem/Standards/DIS-01_Rev4_DER_Interconnection_Standard.pdf', '/filesystem/Standards/DPS-07_Rev2_Distribution_Protection_Standard.pdf']):
    if p.endswith('.pdf'): dump_pdf(p)
    elif p.endswith('.xlsx'): dump_xlsx(p)
"

