python3 -c '
import docx

for p in ["/filesystem/Correspondence/2025-06-27_Backlog_Review_Directive.docx", "/filesystem/Correspondence/2025-07-01_RegAffairs_Tasking_Memo.docx"]:
    print("===", p, "===")
    d = docx.Document(p)
    for para in d.paragraphs:
        if para.text.strip():
            print(para.text)
    for t in d.tables:
        for row in t.rows:
            print(" | ".join(c.text.strip() for c in row.cells))
'

python3 -c '
import os, openpyxl, docx, fitz

for root, dirs, files in os.walk("/filesystem"):
    for fn in sorted(files):
        p = os.path.join(root, fn)
        txt = ""
        try:
            if p.endswith(".pdf"):
                doc = fitz.open(p)
                txt = "\n".join(page.get_text() for page in doc)
            elif p.endswith(".docx"):
                d = docx.Document(p)
                txt = "\n".join(para.text for para in d.paragraphs) + "\n" + "\n".join(" ".join(c.text for c in r.cells) for t in d.tables for r in t.rows)
            elif p.endswith(".xlsx"):
                wb = openpyxl.load_workbook(p, data_only=True)
                for s in wb.sheetnames:
                    ws = wb[s]
                    for r in ws.iter_rows(values_only=True):
                        txt += " ".join(str(x) for x in r if x is not None) + "\n"
            elif p.endswith((".eml", ".txt", ".md", ".csv")):
                txt = open(p, errors="ignore").read()
        except Exception as e:
            pass
        if any(k in txt.lower() for k in ["halbray", "pxa-2024-0002", "aln-159", "kelloway", "ep-25-0418", "tamsworth", "strathe"]):
            print("MATCH:", p)
'

