import pypdf, openpyxl, glob, os

for f in sorted(glob.glob('/filesystem/Correspondence/*Halbray*') + glob.glob('/filesystem/Correspondence/*Kelloway*') + glob.glob('/filesystem/Contracts/**/*', recursive=True) + glob.glob('/filesystem/Commissioning/*Halbray*') + glob.glob('/filesystem/Standards/**/*', recursive=True)):
    if os.path.isfile(f):
        print('====================================')
        print('FILE:', f)
        if f.endswith('.pdf'):
            r = pypdf.PdfReader(f)
            for idx, page in enumerate(r.pages):
                print(f'--- Page {idx+1} ---')
                print(page.extract_text())
        elif f.endswith('.xlsx'):
            wb = openpyxl.load_workbook(f, data_only=True)
            for s in wb.sheetnames:
                print(f'--- Sheet {s} ---')
                ws = wb[s]
                for row in ws.iter_rows(values_only=True):
                    if any(row):
                        print(row)
