python3 -c "
import openpyxl, pypdf, glob

for f in sorted(glob.glob('/filesystem/Standards/**/*', recursive=True)):
    import os
    if os.path.isfile(f):
        print('====================================')
        print('FILE:', f)
        if f.endswith('.pdf'):
            r = pypdf.PdfReader(f)
            print('Pages:', len(r.pages))
            for idx, page in enumerate(r.pages):
                txt = page.extract_text()
                if any(k in txt.lower() for k in ['backfeed', 'halbray', '800', 'ng-xt', 'nordreem', 'cel', '4.1', '3.6', '5.1', '6.2', 'witness', 'pto', 'permission to operate', 'inspection', 'ahj']):
                    print(f'--- Page {idx+1} (matched keywords) ---')
                    print(txt)
        elif f.endswith('.xlsx'):
            wb = openpyxl.load_workbook(f, data_only=True)
            for s in wb.sheetnames:
                ws = wb[s]
                for r_idx, row in enumerate(ws.iter_rows(values_only=True), 1):
                    row_str = ' '.join(str(c) for c in row if c is not None)
                    if any(k in row_str.lower() for k in ['nordreem', 'ng-xt', 'halbray', 'doc no', 'edition']):
                        print(f'{s} R{r_idx}: {row}')
"
